def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    def nearby_foreign(r, c, color):
        score = 0
        for rr in range(max(0, r - 1), min(h, r + 2)):
            for cc in range(max(0, c - 1), min(w, c + 2)):
                if grid[rr][cc] != background and grid[rr][cc] != color:
                    score += 1
        return score

    # Find straight diagonal runs and extend away from the endpoint adjacent
    # to the other colored parts of the figure.
    for color in counts:
        if color == background:
            continue
        for dc in (-1, 1):
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    pr, pc = r - 1, c - dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                        continue

                    run = []
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        run.append((rr, cc))
                        rr += 1
                        cc += dc
                    if len(run) < 2:
                        continue

                    start, end = run[0], run[-1]
                    start_score = nearby_foreign(*start, color)
                    end_score = nearby_foreign(*end, color)

                    if start_score > end_score:
                        rr, cc = end[0] + 1, end[1] + dc
                        step_r, step_c = 1, dc
                    elif end_score > start_score:
                        rr, cc = start[0] - 1, start[1] - dc
                        step_r, step_c = -1, -dc
                    else:
                        continue

                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c

    return out
